#!/usr/bin/env bash
# Removes git-ignored dbt output; all of it is regenerated by `dbt deps` / `dbt build`.
# With --db it also deletes the local dev Postgres container and its data volume.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."

CONTAINER=tilesense-dbt-pg
# Docker Desktop's CLI is not always on PATH.
PATH="/Applications/Docker.app/Contents/Resources/bin:$PATH"

if [[ $# -gt 1 || ( $# -eq 1 && "$1" != "--db" ) ]]; then
  echo "usage: dev/cleanup.sh [--db]" >&2
  exit 2
fi

rm -rf target dbt_packages logs
find . -name .DS_Store -not -path './.git/*' -delete

if [[ $# -eq 1 ]]; then
  if ! command -v docker >/dev/null || ! docker info >/dev/null 2>&1; then
    echo "docker is not available or not running; container $CONTAINER not removed" >&2
    exit 1
  fi
  if docker inspect "$CONTAINER" >/dev/null 2>&1; then
    docker rm -f -v "$CONTAINER" >/dev/null
    echo "Removed container $CONTAINER and its volume"
  else
    echo "No container named $CONTAINER"
  fi
fi
echo "Cleaned analytics/dbt"
